// ---- Edit after importing ----
const ALERT_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const MODEL = 'gpt-4o-mini';
const SKIP_SENDERS = /no-?reply|notifications?@|mailer-daemon/i; // never spend tokens on these
// ------------------------------
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const from = m.from?.value?.[0]?.address || '';
  if (!from || SKIP_SENDERS.test(from)) continue;
  out.push({ json: { model: MODEL, alert_chat_id: ALERT_CHAT_ID, message_id: m.id, thread_id: m.threadId,
    from, from_name: m.from?.value?.[0]?.name || '', subject: String(m.subject || '(no subject)').slice(0, 300),
    body: String(m.text || '').replace(/\n{3,}/g, '\n\n').slice(0, 6000), date: m.date || new Date().toISOString() } });
}
return out.slice(0, 20); // cap per poll

