const src = $('Config').all();
return $input.all().map((item, i) => {
  let d = {};
  try { d = JSON.parse(item.json.choices[0].message.content); } catch (e) { d = { category: 'action', summary: 'Gagal dibaca AI, cek manual.' }; }
  if (!d || typeof d !== 'object') d = {};
  const cats = ['urgent', 'action', 'fyi', 'newsletter', 'spam'];
  const category = cats.includes(d.category) ? d.category : 'action';
  const draft = typeof d.draft_reply === 'string' ? d.draft_reply.replace(/https?:\/\/\S+/g, '[link removed]').slice(0, 3000) : '';
  return { json: { ...src[i].json, category, summary: typeof d.summary === 'string' ? d.summary.slice(0, 300) : '',
    needs_reply: d.needs_reply === true && !!draft && ['urgent', 'action'].includes(category),
    due_date: /^\d{4}-\d{2}-\d{2}$/.test(d.due_date || '') ? d.due_date : '', draft_reply: draft } };
});

const clean = (v, max = 500) => {
  if (v === null || v === undefined) return '';
  let s = String(v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').slice(0, max);
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; // block spreadsheet formula injection
  return s;
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $input.all().map((i) => ({ json: { received_at: i.json.date, from: clean(i.json.from, 200),
  subject: clean(i.json.subject, 300), category: i.json.category, summary: clean(i.json.summary, 300),
  due_date: i.json.due_date, draft_created: i.json.needs_reply ? 'yes' : 'no' } }));

